import{_ as p,a0 as o,w as d,s as r,I as a,x as e,a1 as l,A as i,ao as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何使用 firewall-cmd 管理网络服务 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 firewall-cmd 管理网络服务 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 firewall-cmd 管理网络服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 firewall-cmd 管理网络服务 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200511 How to manage network services with firewall-cmd","title":"如何使用 firewall-cmd 管理网络服务","tag":"202006","desc":""},"relativePath":"202006/20200511 How to manage network services with firewall-cmd.md","filePath":"[post].md"}'),c={name:"202006/20200511 How to manage network services with firewall-cmd.md"};function m(h,s,g,f,u,k){const n=o("Link");return d(),r("div",null,[s[22]||(s[22]=a("h1",{id:"如何使用-firewall-cmd-管理网络服务",tabindex:"-1"},[e("如何使用 firewall-cmd 管理网络服务 "),a("a",{class:"header-anchor",href:"#如何使用-firewall-cmd-管理网络服务","aria-label":"Permalink to “如何使用 firewall-cmd 管理网络服务”"},"​")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202006/03/090806hcmc9cxcbbcuccbe.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("在上一篇文章中，我们探讨了如何在 Fedora 中",-1)),l(n,{href:"https://linux.cn/article-12103-1.html"},{default:i(()=>[...s[0]||(s[0]=[e("用命令行控制防火墙",-1)])]),_:1}),s[2]||(s[2]=e("。",-1))]),s[24]||(s[24]=t(`<p>现在你将看到如何“添加”、“删除”和“列出”服务、协议和端口，以便“阻止”或“允许”它们。</p><h3 id="简短回顾" tabindex="-1">简短回顾 <a class="header-anchor" href="#简短回顾" aria-label="Permalink to “简短回顾”">​</a></h3><p>首先，最好检查一下防火墙的<em>状态</em>，看它是否正在运行。如我们先前所学，你可以使用状态选项（<code>firewall-cmd ‐‐state</code>）来得到。</p><p>下一步是获取网络接口适用的<ruby>域<rt>zone</rt></ruby>。例如，我使用的桌面有两个网络接口：一个<em>物理</em>接口（<code>enp0s3</code>），代表我实际的<em>网卡</em>，和<em>虚拟</em>接口（<code>virbr0</code>），它由 KVM 等虚拟化软件使用。要查看哪些域处于活动状态，请运行 <code>firewall-cmd ‐‐get-active-zones</code>。</p><p>现在，你知道了你感兴趣的域，可以使用 <code>firewall-cmd ‐‐info-zone=FedoraWorkstation</code> 这样的命令列出该域的规则。</p><h3 id="读取区域信息" tabindex="-1">读取区域信息 <a class="header-anchor" href="#读取区域信息" aria-label="Permalink to “读取区域信息”">​</a></h3><p>要显示<em>特定域</em>的信息，请运行 <code>firewall-cmd ‐‐zone=ZoneName ‐‐list-all</code>，或使用以下命令显示默认域的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[dan@localhost ~]$ firewall-cmd --list-all</span></span>
<span class="line"><span>FedoraWorkstation (active)</span></span>
<span class="line"><span>target: default</span></span>
<span class="line"><span>icmp-block-inversion: no</span></span>
<span class="line"><span>interfaces: enp0s3</span></span>
<span class="line"><span>sources:</span></span>
<span class="line"><span>services: dhcpv6-client mdns samba-client ssh</span></span>
<span class="line"><span>ports: 1025-65535/udp 1025-65535/tcp</span></span>
<span class="line"><span>protocols:</span></span>
<span class="line"><span>masquerade: no</span></span>
<span class="line"><span>forward-ports:</span></span>
<span class="line"><span>source-ports:</span></span>
<span class="line"><span>icmp-blocks:</span></span>
<span class="line"><span>rich rules:</span></span></code></pre></div><p>现在，让我们查看输出。第一行表明以下信息关联的域以及该域当前是否在使用中。</p><p><code>target: default</code>：告诉我们这是默认域。可以通过 <code>‐‐set-default-zone=ZoneName</code> 和 <code>‐‐get-default-zone</code> 设置或获取。</p>`,10)),a("p",null,[s[4]||(s[4]=a("code",null,"icmp-block-inversion",-1)),s[5]||(s[5]=e(" 表明是否阻止 ",-1)),l(n,{href:"https://en.wikipedia.org/wiki/Internet_Control_Message_Protocol"},{default:i(()=>[...s[3]||(s[3]=[e("ICMP",-1)])]),_:1}),s[6]||(s[6]=e(" 请求。例如，如果机器响应来自网络上其他机器的 ping 请求。",-1))]),s[25]||(s[25]=t(`<p><code>interfaces</code> 字段显示接受此域的所有接口。</p><h3 id="处理服务、端口和协议" tabindex="-1">处理服务、端口和协议 <a class="header-anchor" href="#处理服务、端口和协议" aria-label="Permalink to “处理服务、端口和协议”">​</a></h3><p>现在，重点关注 <code>services</code>、<code>ports</code> 和 <code>protocols</code> 所在行。默认情况下，防火墙将阻止所有端口、服务和协议，而只允许列出的。</p><p>在这里，你可以看到允许的服务是非常基本的客户端服务。例如，访问网络上的共享文件夹（<code>samba-client</code>）、与 DNS 服务器通信或通过 SSH（<code>ssh</code> 服务）连接到计算机。你可以将 <code>service</code> 视为与端口组合的协议，例如 <code>ssh</code> 服务使用 SSH 协议，并且按照惯例使用 22 端口。通过允许 <code>ssh</code> 服务，你实际上所做的就是允许传入的连接在默认 22 端口上使用 SSH 协议。</p><p>请注意，根据经验，名称中带有 <code>client</code> 字样的服务是指传出连接，也就是你使用你的 IP 作为源对外部的<em>连接</em>，与之相反的是 <code>ssh</code> 服务，比如，它将接受传入连接（监听来自外部的连接）。</p><p>你可以在文件 <code>/etc/services</code> 中查找服务。例如，如果你想知道这些服务使用什么端口和协议：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[dan@localhost ~]$ cat /etc/services | grep ssh</span></span>
<span class="line"><span>ssh 22/tcp # The Secure Shell (SSH) Protocol</span></span>
<span class="line"><span>ssh 22/udp # The Secure Shell (SSH) Protocol</span></span></code></pre></div><p>你可以看到 SSH 同时使用 TCP 和 UDP 的 22 端口。此外，如果你希望查看所有可用的服务，只需使用 <code>firewall-cmd --get-services</code>。</p><h4 id="打开端口" tabindex="-1">打开端口 <a class="header-anchor" href="#打开端口" aria-label="Permalink to “打开端口”">​</a></h4><p>如果要阻止端口、服务或协议，请确保在此处未列出它们。展开来说，如果要允许服务，那么需要将它添加到列表中。</p><p>假设你要打开 <code>5000</code> 端口用于 TCP 连接。为此，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo firewall-cmd --zone=FedorwaWorkstation --permanent --add-port=5000/tcp</span></span></code></pre></div><p>请注意，你需要指定规则适用的域。添加规则时，还需要如上指定它是 <code>tcp</code> 还是 <code>udp</code> 端口。<code>--permanent</code> 参数将规则设置为即使系统重启后也可以保留。</p><p>再次查看你所在区域的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[dan@localhost ~]$ firewall-cmd --list-all</span></span>
<span class="line"><span>FedoraWorkstation (active)</span></span>
<span class="line"><span>target: default</span></span>
<span class="line"><span>icmp-block-inversion: no</span></span>
<span class="line"><span>interfaces: enp0s3</span></span>
<span class="line"><span>sources:</span></span>
<span class="line"><span>services: dhcpv6-client mdns samba-client ssh</span></span>
<span class="line"><span>ports: 1025-65535/udp 1025-65535/tcp 5000/tcp</span></span>
<span class="line"><span>protocols:</span></span>
<span class="line"><span>masquerade: no</span></span>
<span class="line"><span>forward-ports:</span></span>
<span class="line"><span>source-ports:</span></span>
<span class="line"><span>icmp-blocks:</span></span>
<span class="line"><span>rich rules:</span></span></code></pre></div><p>类似地，如果你想从列表删除该端口，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo firewall-cmd --zone=FedorwaWorkstation --permanent --remove-port=5000/tcp</span></span></code></pre></div><p>相同的 <code>remove</code> （<code>‐‐remove-protocol</code>、<code>‐‐remove-service</code>） 和 <code>add</code>（<code>‐‐add-protocol</code>、<code>‐‐add-service</code>）选项同样适用于<em>服务</em>和<em>协议</em>。</p><hr>`,19)),a("p",null,[s[8]||(s[8]=e("via: ",-1)),l(n,{href:"https://fedoramagazine.org/how-to-manage-network-services-with-firewall-cmd/"},{default:i(()=>[...s[7]||(s[7]=[e("https://fedoramagazine.org/how-to-manage-network-services-with-firewall-cmd/",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("作者：",-1)),l(n,{href:"https://fedoramagazine.org/author/dan01/"},{default:i(()=>[...s[9]||(s[9]=[e("dan01",-1)])]),_:1}),s[14]||(s[14]=e(" 选题：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[10]||(s[10]=[e("lujun9972",-1)])]),_:1}),s[15]||(s[15]=e(" 译者：",-1)),l(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[11]||(s[11]=[e("geekpi",-1)])]),_:1}),s[16]||(s[16]=e(" 校对：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=e("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原创编译，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...s[18]||(s[18]=[e("Linux中国",-1)])]),_:1}),s[21]||(s[21]=e(" 荣誉推出",-1))])])}const C=p(c,[["render",m]]);export{v as __pageData,C as default};
